		markCompleted() {
			audit.completed++;
		},
		model,
		controls,
		audit,
		router,
		security: account.security,
		account,
		setRead(value: ReadMode) {
			controls.readMode = value;
		},
		setSave(value: SaveMode) {
			controls.saveMode = value;
		},
		toggleDisabled() {
			controls.disabled = !controls.disabled;
		},
		toggleDenied() {
			controls.denied = !controls.denied;
		},
		async toggleReadonly() {
			controls.readonly = !controls.readonly;
			account.controls.readOnly = controls.readonly;
			await account.security.refresh();
		},
		replaceService() {
			raw.services.settings = (subject, request) =>
				initialServices.settings(subject, request);
			raw.services.save = (subject, input, request) =>
				initialServices.save(subject, input, request);
			raw.services.verifySave = (subject, id, request) =>
				initialServices.verifySave!(subject, id, request);
