import { computed, reactive } from 'vue';
import type { AccountSettingsCompanion } from '../Session.js';

/** Two page-local preferences; reminders/digest remain original AccountSettings fields. */
export interface LocalPreferences {
	projectUpdates: boolean;
	systemNotices: boolean;
}
export function createLocalPreferences() {
	const original = reactive<LocalPreferences>({ projectUpdates: false, systemNotices: false });
	const draft = reactive<LocalPreferences>({ ...original });
	let read: { id: string; value: LocalPreferences } | undefined;
	let captured:
		| {
				id: string;
				value: LocalPreferences;
				field?: keyof LocalPreferences;
				selective: boolean;
		  }
		| undefined;
	const dirty = computed(
		() =>
			draft.projectUpdates !== original.projectUpdates ||
			draft.systemNotices !== original.systemNotices
	);
	function copy(value: LocalPreferences): LocalPreferences {
		if (typeof value?.projectUpdates !== 'boolean' || typeof value?.systemNotices !== 'boolean')
			throw new Error('Invalid local preferences');
		return { projectUpdates: value.projectUpdates, systemNotices: value.systemNotices };
	}
	const companion: AccountSettingsCompanion = {
		dirty: () => dirty.value,
		loaded(id) {
			if (read?.id !== id) throw new Error('Missing staged preferences');
			Object.assign(original, read.value);
			Object.assign(draft, read.value);
			read = undefined;
		},
		capture(id, notification) {
			const value = copy(notification ? original : draft);
			const field = notification?.field;
			if (notification && (field === 'projectUpdates' || field === 'systemNotices')) {
				value[field] = notification.value;
				draft[field] = notification.value;
				captured = { id, value, field, selective: true };
			} else captured = { id, value, selective: !!notification };
		},
		accept(id) {
			if (captured?.id !== id) throw new Error('Mismatched preference operation');
			Object.assign(original, captured.value);
			if (!captured.selective) Object.assign(draft, captured.value);
			captured = undefined;
		},
		rollbackNotification(id) {
			if (captured?.id !== id) return;
			if (captured.field) draft[captured.field] = original[captured.field];
			captured = undefined;
		},
		revert() {
			Object.assign(draft, original);
		},
		clear() {
			read = undefined;
			captured = undefined;
			Object.assign(original, { projectUpdates: false, systemNotices: false });
			Object.assign(draft, original);
		}
	};
	return {
		draft,
		dirty,
		companion,
		stageRead(id: string, value: LocalPreferences) {
			read = { id, value: copy(value) };
		},
		pending(id: string) {
			if (captured?.id !== id) throw new Error('Missing original save capture');
			return Object.freeze(copy(captured.value));
		},
		set(key: keyof LocalPreferences, value: boolean) {
			draft[key] = value;
		}
	};
}
export type LocalPreferenceDraft = ReturnType<typeof createLocalPreferences>;

import { createApp, shallowRef } from 'vue';
